import{Z as t,e as i,f as a,a0 as n}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Multi-Site Notification Content","description":"","frontmatter":{},"headers":[],"relativePath":"guides/email-notifications/multi-site-notification-content.md","filePath":"guides/email-notifications/multi-site-notification-content.md","lastUpdated":1782532814000}'),o={name:"guides/email-notifications/multi-site-notification-content.md"};function s(r,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="multi-site-notification-content" tabindex="-1">Multi-Site Notification Content <a class="header-anchor" href="#multi-site-notification-content" aria-label="Permalink to &quot;Multi-Site Notification Content&quot;">​</a></h1><p>Multi-site forms often need notification emails in the right language with the right recipients — without duplicating every form. Formie supports per-site notification overrides in the builder, conditional notifications, and variable-driven single templates. This guide compares the patterns and recommends one for common setups.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Craft multi-site with Formie forms enabled on multiple sites</li><li><a href="/forms/email-notifications">Email Notifications</a></li><li><a href="/forms/multi-site-and-translation">Multi-Site &amp; Translation</a></li><li><a href="/forms/translations">Translations</a></li></ul><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>A contact form runs on English and French sites. You need:</p><ul><li>French confirmation email copy for French submissions</li><li>English copy for English submissions</li><li>Possibly different internal recipients per region</li></ul><p>Form field labels use <a href="/forms/multi-site-and-translation#content-translation">site overrides</a>. Notifications need a deliberate strategy too.</p><h2 id="pattern-1-—-per-site-notification-overrides-builder" tabindex="-1">Pattern 1 — Per-Site Notification Overrides (Builder) <a class="header-anchor" href="#pattern-1-—-per-site-notification-overrides-builder" aria-label="Permalink to &quot;Pattern 1 — Per-Site Notification Overrides (Builder)&quot;">​</a></h2><p>Notification subject and body can be edited per site in the form builder. Overrides store in <code>formie_form_site_overrides</code> with other translation data.</p><p><strong>Workflow:</strong></p><ol><li>Build the notification on the source site (English)</li><li>Switch site in the builder to French</li><li>Edit the notification subject and body in French</li><li>Save</li></ol><p><strong>Pros:</strong> Editor-managed, no deploy, matches how field labels are translated</p><p><strong>Cons:</strong> Queued sends and CLI context must resolve the submission&#39;s site correctly (Formie does this when the submission has <code>siteId</code>); harder to see all languages at once</p><p><strong>Best for:</strong> Marketing teams managing copy in the CP</p><h2 id="pattern-2-—-separate-notifications-with-conditions" tabindex="-1">Pattern 2 — Separate Notifications with Conditions <a class="header-anchor" href="#pattern-2-—-separate-notifications-with-conditions" aria-label="Permalink to &quot;Pattern 2 — Separate Notifications with Conditions&quot;">​</a></h2><p>Create one notification per language (or region), each with a <a href="/forms/conditions">condition</a> on site or language:</p><table tabindex="0"><thead><tr><th>Notification</th><th>Condition</th><th>Recipients</th></tr></thead><tbody><tr><td>Admin — EN</td><td>Site is English</td><td><code>enquiries@example.com</code></td></tr><tr><td>Admin — FR</td><td>Site is French</td><td><code>demandes@example.com</code></td></tr><tr><td>User confirmation — EN</td><td>Site is English</td><td><code>{field:email}</code></td></tr><tr><td>User confirmation — FR</td><td>Site is French</td><td><code>{field:email}</code></td></tr></tbody></table><p>Use Craft site variables in conditions (current site at submit time matches submission site).</p><p><strong>Pros:</strong> Explicit delivery logic; easy to audit in the notifications list; clear enable/disable per language</p><p><strong>Cons:</strong> More rows in the notifications tab; condition edits require builder access</p><p><strong>Best for:</strong> Different recipients per site, or when legal requires separate templates per jurisdiction</p><h2 id="pattern-3-—-single-notification-with-variables" tabindex="-1">Pattern 3 — Single Notification with Variables <a class="header-anchor" href="#pattern-3-—-single-notification-with-variables" aria-label="Permalink to &quot;Pattern 3 — Single Notification with Variables&quot;">​</a></h2><p>One notification body using the <a href="/developers/reference-tokens">variable picker</a>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thank you for contacting {site:name}.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{allFields}</span></span></code></pre></div><p>Or custom Twig in an <a href="/guides/email-notifications/building-an-email-notification-template-from-scratch">email template</a> that branches on <code>{site:handle}</code> or locale.</p><p><strong>Pros:</strong> One notification to maintain; good when only small differences (site name, footer address)</p><p><strong>Cons:</strong> Complex branching in one template gets messy; translators cannot use the simple content editor for full bodies</p><p><strong>Best for:</strong> Minor per-site differences, shared layout</p><h2 id="what-about-translation-files" tabindex="-1">What About Translation Files? <a class="header-anchor" href="#what-about-translation-files" aria-label="Permalink to &quot;What About Translation Files?&quot;">​</a></h2><p>Do <strong>not</strong> put notification subject/body in <code>translations/*/formie.php</code>. Notification copy edited in the builder belongs in the database (or site overrides) — same rule as field labels. See <a href="/forms/translations">Translations</a>.</p><p>Plugin-owned strings in email <em>templates</em> (button labels, footer legal boilerplate shared across notifications) can use <code>site.php</code> or Twig <code>craft.app.language</code>.</p><h2 id="submission-site-matters" tabindex="-1">Submission Site Matters <a class="header-anchor" href="#submission-site-matters" aria-label="Permalink to &quot;Submission Site Matters&quot;">​</a></h2><p>Submissions store <code>siteId</code>. When Formie sends notifications:</p><ol><li>The submission&#39;s site determines which <a href="/forms/multi-site-and-translation">site overrides</a> merge into field values in <code>{allFields}</code> output</li><li>Conditions evaluate against submission context</li><li>Variable tokens resolve for that site</li></ol><p>Ensure headless submits pass the correct <code>siteId</code> when creating submissions via GraphQL.</p><h2 id="queue-and-cli-behaviour" tabindex="-1">Queue and CLI Behaviour <a class="header-anchor" href="#queue-and-cli-behaviour" aria-label="Permalink to &quot;Queue and CLI Behaviour&quot;">​</a></h2><p>With <code>useQueueForNotifications</code> enabled (recommended), notifications queue after submit. The queued job carries submission ID and site context — per-site overrides apply the same as synchronous sends.</p><p>Test both:</p><ul><li>Front-end submit on each site</li><li>Control panel test send while viewing each site in the builder</li></ul><h2 id="recommended-starting-point" tabindex="-1">Recommended Starting Point <a class="header-anchor" href="#recommended-starting-point" aria-label="Permalink to &quot;Recommended Starting Point&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Pattern</th></tr></thead><tbody><tr><td>EN/FR labels only, same recipients</td><td>Pattern 1 (overrides) or Pattern 3 (variables)</td></tr><tr><td>Different inboxes per country</td><td>Pattern 2 (conditions)</td></tr><tr><td>Legal requires separate templates</td><td>Pattern 2</td></tr><tr><td>Headless multi-site SPA</td><td>Pattern 2 + explicit <code>siteId</code> on submit</td></tr></tbody></table><p>Many projects combine Pattern 2 for admin emails (fixed recipients per site) with Pattern 1 for user confirmations (translated copy).</p><h2 id="deliverability-reminder" tabindex="-1">Deliverability Reminder <a class="header-anchor" href="#deliverability-reminder" aria-label="Permalink to &quot;Deliverability Reminder&quot;">​</a></h2><p>Multi-site does not change mail best practices — use a consistent <strong>From</strong> you control, put the submitter in <strong>Reply-To</strong>, and set up SPF/DKIM/DMARC. See <a href="/guides/email-notifications/how-to-keep-email-notifications-out-of-your-junk-emails">How to keep Email Notifications out of your junk emails</a>.</p>`,45)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
